let translations={de:{},uk:{},ru:{},en:{}};
function setLang(lang){const data=translations[lang]||translations.de;document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(data[k]) el.textContent=data[k];});document.querySelectorAll('.language-switch button').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));localStorage.setItem('fsl_lang',lang)}
document.querySelectorAll('.language-switch button').forEach(btn=>btn.addEventListener('click',()=>setLang(btn.dataset.lang)));
document.querySelector('.menu-toggle').addEventListener('click',()=>document.getElementById('mainNav').classList.toggle('open'));
document.querySelectorAll('.main-nav a').forEach(a=>a.addEventListener('click',()=>document.getElementById('mainNav').classList.remove('open')));
setLang('de');

// v12: JSON-driven cyclic sliders
function initSliders(){
 document.querySelectorAll('[data-slider]').forEach(slider=>{
  const track=slider.querySelector('.slider-track'),slides=Array.from(slider.querySelectorAll('.slider-slide')),counter=slider.querySelector('.slider-counter');if(!slides.length)return;
  let index=0,touchStartX=null;const show=next=>{index=(next+slides.length)%slides.length;track.style.transform=`translateX(-${index*100}%)`;counter.textContent=`${index+1} / ${slides.length}`};
  slider.querySelector('.slider-prev').onclick=()=>show(index-1);slider.querySelector('.slider-next').onclick=()=>show(index+1);
  track.addEventListener('touchstart',e=>{touchStartX=e.changedTouches[0].clientX},{passive:true});track.addEventListener('touchend',e=>{if(touchStartX===null)return;const d=e.changedTouches[0].clientX-touchStartX;if(Math.abs(d)>=45)show(d<0?index+1:index-1);touchStartX=null},{passive:true});show(0);
 });
}
document.querySelectorAll('[data-placeholder-link="true"]').forEach(link => {
  link.addEventListener('click', event => event.preventDefault());
});



