function initBlogCarousel(){
 const carousel=document.querySelector('[data-blog-carousel]'); if(!carousel)return;
 const track=carousel.querySelector('.blog-grid'), cards=Array.from(track.querySelectorAll('.blog-card')), prev=carousel.querySelector('.blog-prev'), next=carousel.querySelector('.blog-next'), counter=carousel.querySelector('.blog-counter');
 if(!cards.length){if(counter)counter.textContent='0 / 0';return;} let index=0;
 const update=()=>counter&&(counter.textContent=`${index+1} / ${cards.length}`);
 const go=n=>{index=(n+cards.length)%cards.length;cards[index].scrollIntoView({behavior:'smooth',block:'nearest',inline:'start'});update()};
 if(prev)prev.onclick=()=>go(index-1); if(next)next.onclick=()=>go(index+1); update();
}
