function isoLocal(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function boolValue(value,defaultValue=true){if(value===undefined||value===null)return defaultValue;if(typeof value==='string')return !['false','0','no','off'].includes(value.toLowerCase());return Boolean(value)}
function firstArray(data,keys){if(Array.isArray(data))return data;for(const key of keys){if(Array.isArray(data?.[key]))return data[key]}return []}
function weekdayValue(value){
 if(typeof value==='number')return value===0?7:value;
 const raw=String(value??'').trim().toLowerCase();const number=Number(raw);if(Number.isFinite(number)&&number>=0&&number<=7)return number===0?7:number;
 const days={monday:1,mon:1,montag:1,понеділок:1,понедельник:1,tuesday:2,tue:2,dienstag:2,вівторок:2,вторник:2,wednesday:3,wed:3,mittwoch:3,середа:3,среда:3,thursday:4,thu:4,donnerstag:4,четвер:4,четверг:4,friday:5,fri:5,freitag:5,пʼятниця:5,пятница:5,saturday:6,sat:6,samstag:6,субота:6,суббота:6,sunday:7,sun:7,sonntag:7,неділя:7,воскресенье:7};return days[raw]||null;
}
function normalizeEvent(event,index=0){return {...event,id:event.id??event.eventId??`event_${index}`,serviceId:event.serviceId??event.service_id??event.service??event.procedureId??event.procedure_id??'',weekday:weekdayValue(event.weekday??event.dayOfWeek??event.day_of_week??event.day),time:event.time??event.startTime??event.start_time??'',duration:event.duration??event.durationMinutes??event.duration_minutes??60,startDate:event.startDate??event.start_date??null,endDate:event.endDate??event.end_date??null,date:event.date??event.eventDate??event.event_date??null,visible:boolValue(event.visible,true),bookingAvailable:boolValue(event.bookingAvailable??event.booking_available,true)}}
function normalizeRegularData(data){const source=firstArray(data,['regularEvents','events','schedule','items']);return {regularEvents:source.map(normalizeEvent).filter(event=>event.serviceId)}}
function normalizeExceptionsData(data,regularSource){
 const source=firstArray(data,['exceptions','events','schedule','items']);
 const datedRegular=firstArray(regularSource,['regularEvents','events','schedule','items']).map(normalizeEvent).filter(event=>event.date);
 return {exceptions:[...source.map((event,index)=>{const normalized=normalizeEvent(event,index);let type=String(event.type??event.eventType??event.event_type??'').toLowerCase();if(['one-time','one_time','once','single','addition'].includes(type))type='add';if(['cancel','cancelled','canceled','remove','delete'].includes(type))type='exclude';if(!type&&normalized.date)type='add';return {...normalized,type,regularEventId:event.regularEventId??event.regular_event_id??event.parentId??event.parent_id??null}}),...datedRegular.map(event=>({...event,type:'add'}))]};
}
function applicableRegular(date){
 const iso=isoLocal(date), weekday=date.getDay()===0?7:date.getDay();
 return regularData.regularEvents.filter(e=>e.visible!==false&&!e.date&&weekdayValue(e.weekday)===weekday&&(!e.startDate||iso>=e.startDate)&&(!e.endDate||iso<=e.endDate));
}
function eventsForDate(date){
 const iso=isoLocal(date); let events=applicableRegular(date).map(e=>({id:e.id,regularEventId:e.id,serviceId:e.serviceId,time:e.time,duration:e.duration,bookingAvailable:e.bookingAvailable!==false,source:'regular'}));
 const ex=exceptionsData.exceptions.filter(x=>x.date===iso&&x.visible!==false);
 const excluded=new Set(ex.filter(x=>x.type==='exclude').map(x=>x.regularEventId)); events=events.filter(e=>!excluded.has(e.regularEventId));
 ex.filter(x=>x.type==='add').forEach(x=>events.push({id:x.id,serviceId:x.serviceId,time:x.time||'',duration:x.duration,bookingAvailable:x.bookingAvailable!==false,source:'exception'}));
 return events.sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));
}
function renderCalendar(){
 const desktop=document.getElementById('calendarDesktop'), mobile=document.getElementById('calendarMobile'); if(!desktop||!mobile)return;
 const lang=currentLang(), locale=lang==='uk'?'uk-UA':lang==='en'?'en-GB':lang==='ru'?'ru-RU':'de-DE'; const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 document.getElementById('calendarTitle').textContent=new Intl.DateTimeFormat(locale,{month:'long',year:'numeric'}).format(calendarDate);
 const labels={de:['Mo','Di','Mi','Do','Fr','Sa','So'],uk:['Пн','Вт','Ср','Чт','Пт','Сб','Нд'],ru:['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],en:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']}; desktop.innerHTML=labels[lang].map(d=>`<div class="cal-head">${d}</div>`).join(''); mobile.innerHTML='';
 let first=(new Date(y,m,1).getDay()+6)%7; for(let i=0;i<first;i++)desktop.innerHTML+='<div class="cal-day empty"></div>'; const count=new Date(y,m+1,0).getDate(), groups=[];
 for(let d=1;d<=count;d++){const date=new Date(y,m,d),evs=eventsForDate(date),past=date<today,isToday=date.toDateString()===now.toDateString();desktop.innerHTML+=`<div class="cal-day ${isToday?'today':''} ${past?'past':''}"><div class="cal-num">${d}</div>${evs.map(e=>`<button class="cal-event${e.bookingAvailable===false?' booking-unavailable':''}" data-service="${e.serviceId}" data-date="${isoLocal(date)}" data-booking-available="${e.bookingAvailable!==false}" ${e.bookingAvailable===false?'disabled title="'+translations[lang].bookingUnavailable+'"':''}>${e.time?e.time+' · ':''}${serviceTitle(e.serviceId,lang)} · ${translations[lang].from10}</button>`).join('')}</div>`;if(evs.length&&!past)groups.push({date,evs});}
 if(!groups.length)mobile.innerHTML=`<p class="calendar-empty">${translations[lang].noUpcomingClasses}</p>`; else {const lim=8;mobile.innerHTML=groups.map((g,i)=>`<div class="mobile-day${i>=lim?' mobile-day-extra':''}"><div class="mobile-date">${new Intl.DateTimeFormat(locale,{weekday:'short',day:'numeric',month:'short'}).format(g.date)}</div><div class="mobile-events">${g.evs.map(e=>`<button class="cal-event${e.bookingAvailable===false?' booking-unavailable':''}" data-service="${e.serviceId}" data-date="${isoLocal(g.date)}" data-booking-available="${e.bookingAvailable!==false}" ${e.bookingAvailable===false?'disabled title="'+translations[lang].bookingUnavailable+'"':''}><span class="event-time">${e.time||'—'}</span><span class="event-name">${serviceTitle(e.serviceId,lang)}</span><span class="event-price">${e.bookingAvailable===false?translations[lang].bookingUnavailable:translations[lang].from10}</span></button>`).join('')}</div></div>`).join('');if(groups.length>lim){mobile.innerHTML+=`<button type="button" class="calendar-more" id="calendarMore">${translations[lang].showMoreClasses}</button>`;document.getElementById('calendarMore').onclick=e=>{mobile.querySelectorAll('.mobile-day-extra').forEach(x=>x.classList.remove('mobile-day-extra'));e.currentTarget.remove()}}}
 document.querySelectorAll('.cal-event').forEach(b=>b.onclick=()=>{if(b.dataset.bookingAvailable==='false')return;const service=pricesData?.services?.find(s=>s.id===b.dataset.service);const type=service?.category==='massage'?'massage':'training';openBookingChoices({serviceId:b.dataset.service,date:b.dataset.date,label:`${serviceTitle(b.dataset.service,lang)} | ${b.dataset.date}`},type);});
}
