function openSiteBooking(){closeBookingChoices();const form=document.getElementById('bookingForm');if(!form)return;renderBookingForm();form.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>document.getElementById('bookingName')?.focus({preventScroll:true}),550)}
function sendSiteBooking(){if(document.querySelector('.site-booking-submit')?.disabled)return;const email=siteConfig?.booking?.email||'pisarevskaya.ks@gmail.com';const subject={de:'Buchungsanfrage über die Website',uk:'Запит на запис із сайту',ru:'Запрос на запись с сайта',en:'Booking request from website'}[currentLang()];location.href=`mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bookingText())}`}
function updateBookingLinks(){const tg=document.getElementById('bookTelegram'),wa=document.getElementById('bookWhatsApp');if(tg){const ok=!!universalTelegramUrl();tg.classList.toggle('disabled',!ok);tg.setAttribute('aria-disabled',ok?'false':'true')}if(wa){const ok=!!universalWhatsAppUrl();wa.classList.toggle('disabled',!ok);wa.setAttribute('aria-disabled',ok?'false':'true')}}
document.querySelectorAll('.booking-trigger').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();openBookingChoices({},el.dataset.bookingType==='massage'?'massage':'training')}));
document.querySelector('.booking-choice-close')?.addEventListener('click',closeBookingChoices);
document.getElementById('bookingChoiceModal')?.addEventListener('click',e=>{if(e.target.id==='bookingChoiceModal')closeBookingChoices()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeBookingChoices()});
document.getElementById('bookTelegram')?.addEventListener('click',e=>{e.preventDefault();if(e.currentTarget.getAttribute('aria-disabled')==='true')return;openTelegramBooking()});
document.getElementById('bookWhatsApp')?.addEventListener('click',e=>{e.preventDefault();if(e.currentTarget.getAttribute('aria-disabled')==='true')return;openWhatsAppBooking()});
document.getElementById('bookOnSite')?.addEventListener('click',openSiteBooking);
document.getElementById('bookingDate')?.addEventListener('change',()=>{bookingContext.date='';bookingContext.serviceId='';renderBookingOptions()});
['bookingName','bookingContact','bookingOption'].forEach(id=>document.getElementById(id)?.addEventListener('input',validateBookingForm));
document.getElementById('bookingOption')?.addEventListener('change',validateBookingForm);
document.querySelector('.site-booking-submit')?.addEventListener('click',sendSiteBooking);
const publicTransportToggle=document.getElementById('publicTransportToggle');
const mdvWidget=document.getElementById('mdvWidget');
publicTransportToggle?.addEventListener('click',()=>{
 const opening=mdvWidget?.hasAttribute('hidden');if(!mdvWidget)return;
 if(opening){
   mdvWidget.removeAttribute('hidden');
   if(!mdvWidget.querySelector('iframe')){
     mdvWidget.innerHTML='<div class="mdv-widget-loading">MDV Fahrtenplaner wird geladen …</div>';
     const iframe=document.createElement('iframe');iframe.title='MDV Fahrtenplaner';iframe.loading='lazy';iframe.referrerPolicy='strict-origin-when-cross-origin';iframe.src='https://reiseauskunft.insa.de/auskunft-iframe/?S=&Z=Leipzig%2C%20Lutherstra%C3%9Fe%2014&timeSel=depart&L=vs_mdv';iframe.addEventListener('load',()=>mdvWidget.querySelector('.mdv-widget-loading')?.remove());mdvWidget.appendChild(iframe);
   }
   setTimeout(()=>mdvWidget.scrollIntoView({behavior:'smooth',block:'nearest'}),60);
 }else mdvWidget.setAttribute('hidden','');
 publicTransportToggle.setAttribute('aria-expanded',opening?'true':'false');
});
const navigationModal=document.getElementById('navigationModal');
const closeNavigation=()=>{navigationModal?.classList.remove('open');navigationModal?.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')};
document.getElementById('carNavigationToggle')?.addEventListener('click',()=>{navigationModal?.classList.add('open');navigationModal?.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')});
document.querySelector('.navigation-close')?.addEventListener('click',closeNavigation);
navigationModal?.addEventListener('click',event=>{if(event.target===navigationModal)closeNavigation()});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeNavigation()});
const originalSetLang=setLang; setLang=function(lang){originalSetLang(lang);renderPrices();renderBlog();renderCalendar();renderBookingForm();renderReviews()};
function escapeHtml(value){const node=document.createElement('div');node.textContent=String(value??'');return node.innerHTML}
function renderGalleries(){galleriesData.galleries.forEach(g=>{const track=document.querySelector(`[data-slider="${g.id}"] .slider-track`);if(!track)return;const photos=(g.photos||[]).filter(p=>p.visible!==false).sort((a,b)=>(a.order||0)-(b.order||0));track.innerHTML=photos.map((p,i)=>`<div class="slider-slide"><img alt="Fitness Stretching Leipzig ${escapeHtml(g.id)} ${i+1}" loading="lazy" src="${escapeHtml(p.image)}"></div>`).join('')});initSliders()}
function applySiteImages(){const images=siteConfig.images||{},hero=document.querySelector('.hero-image'),intro=document.querySelector('.intro-image img');if(hero&&images.hero)hero.style.backgroundImage=`url("${images.hero}")`;if(intro&&images.intro)intro.src=images.intro;const keys=['stretching','pilates','barre','highheels','ladydance','pregnancy','kids3','kids9'];document.querySelectorAll('.course-image').forEach((img,i)=>{if(images.courses?.[keys[i]])img.src=images.courses[keys[i]]})}
function renderReviews(){const reviews=(reviewsData.reviews||[]).slice(0,6),grid=document.getElementById('reviewsGrid'),empty=document.getElementById('reviewsEmpty'),summary=document.getElementById('reviewsSummary'),link=document.getElementById('reviewsGoogleLink');if(link)link.href=reviewsData.googleUrl||siteConfig.reviews?.googleUrl||link.href;if(grid)grid.innerHTML=reviews.map(r=>`<article class="review-card"><div class="review-stars" aria-label="${Number(r.rating)||5} / 5">${'★'.repeat(Math.max(0,Math.min(5,Number(r.rating)||5)))}</div><p>“${escapeHtml(r.text||r.comment||'')}”</p><strong>${escapeHtml(r.author||r.authorName||'Google')}</strong><small>${escapeHtml(r.relativeTime||r.date||'')}</small></article>`).join('');if(empty)empty.hidden=reviews.length>0;if(summary){const rating=Number(reviewsData.rating);summary.hidden=!rating;summary.textContent=rating?`Google · ${rating.toFixed(1)} ★${reviewsData.totalReviewCount?` · ${reviewsData.totalReviewCount}`:''}`:''}}
async function loadV9(){
 const fetchJson=async(url,fallback)=>{try{const separator=url.includes('?')?'&':'?';const response=await fetch(`${url}${separator}v=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error(`${response.status} ${url}`);return await response.json()}catch(error){console.warn(`JSON fetch unavailable: ${url}`,error);return fallback}};
 const fallbackConfig={social:{whatsapp:'https://wa.me/4917624785836',telegram:''},booking:{whatsapp:'https://wa.me/4917624785836',whatsappMassage:'https://wa.me/4915226130049',telegram:'',email:'pisarevskaya.ks@gmail.com'}};
 const loadedConfig=await fetchJson('config/site.json',fallbackConfig);const [loadedI18n,loadedPrices,loadedBlog,loadedRegular,loadedExceptions,loadedTheme,loadedSections,loadedGalleries,fallbackReviews]=await Promise.all([fetchJson('content/i18n.json',{translations}),fetchJson('content/prices.json',fallbackPrices),fetchJson('content/blog.json',fallbackBlog),fetchJson('content/regular_schedule.json',fallbackRegular),fetchJson('content/schedule_exceptions.json',fallbackExceptions),fetchJson('config/theme.json',fallbackTheme),fetchJson('config/sections.json',fallbackSections),fetchJson('content/galleries.json',{galleries:[]}),fetchJson(loadedConfig.reviews?.fallbackFile||'content/reviews.json',{reviews:[]})]);const apiReviews=loadedConfig.reviews?.apiUrl?await fetchJson(loadedConfig.reviews.apiUrl,null):null;
 translations=loadedI18n.translations||translations;pricesData={services:firstArray(loadedPrices,['services','items'])};blogData={articles:firstArray(loadedBlog,['articles','items'])};regularData=normalizeRegularData(loadedRegular);exceptionsData=normalizeExceptionsData(loadedExceptions,loadedRegular);galleriesData={galleries:firstArray(loadedGalleries,['galleries','items'])};reviewsData=apiReviews||fallbackReviews;siteConfig=loadedConfig||fallbackConfig;
 applyTheme(loadedTheme);applySections(loadedSections);applySiteImages();renderGalleries();renderReviews();
 updateBookingLinks();
 setLang(localStorage.getItem('fsl_lang')||siteConfig.defaultLanguage||'de');
}
loadV9();
